  const rules = new Set(findings(report).map((f) => f.rule).filter(Boolean));
  const authored = [...rules].filter((rule) => !DERIVABLE.has(rule));
  if (authored.length === rules.size) return { folder, planned: [], authored };

  const edits = [];
